/// Acknowledges a `SwapSigilUnit` request (contract §13, message id `0x0021`, `E→T`).
/// `#[non_exhaustive]` with `Default`: the facade builds it outside `grimoire_debug`
/// (contract §2 rule 13).
#[non_exhaustive]
#[derive(Clone, Default, PartialEq, Debug)]
pub struct SwapAck {
    /// `seq` of the triggering `SwapSigilUnit` frame.
    pub in_reply_to: u32,
    /// `0` applied, `1` rejected, `2` superseded by a later swap of the same unit.
    pub status: u8,
    /// First tick that ran with the new unit; `0` if not applied.
    pub applied_tick: u64,
    /// Number of Sigil unit swaps applied so far (after this one, if applied).
    pub content_swaps: u32,
    /// Content epoch after this swap (contract §11.8).
    pub content_manifest: u64,
    /// The swapped unit's `SigilUnit::content_hash`.
    pub unit_hash: u64,
    /// Human-readable detail when `status != 0`.
    pub reason: String,
}

impl SwapAck {
    /// Encodes this payload (contract §2 rule 9): fails with `FieldTooLong` for the
    /// first field whose length or count exceeds its declared maximum.
    pub fn encode(&self, out: &mut Vec<u8>) -> Result<(), ProtocolError> {
        let mut writer = Writer::new(out);
        writer.u32(self.in_reply_to);
        writer.u8(self.status);
        writer.u64(self.applied_tick);
        writer.u32(self.content_swaps);
        writer.u64(self.content_manifest);
        writer.u64(self.unit_hash);
        writer.str_u32("reason", 1024, &self.reason)?;
        Ok(())
    }

    /// Decodes this payload from exactly `bytes`: [`ProtocolError::TrailingBytes`] if
    /// any byte is left over (contract §13).
    pub fn decode(bytes: &[u8]) -> Result<Self, ProtocolError> {
        let mut reader = Reader::new(bytes);
        let value = Self::decode_from(&mut reader)?;
        reader.finish()?;
        Ok(value)
    }

    /// Decodes this payload from `reader`, leaving the read head after its last byte
    /// and any trailing bytes unconsumed (used when nested inside a `vec`/`option`;
    /// only the outermost [`Self::decode`] enforces "no trailing bytes").
    fn decode_from(reader: &mut Reader<'_>) -> Result<Self, ProtocolError> {
        let in_reply_to = reader.u32()?;
        let status = reader.u8()?;
        let applied_tick = reader.u64()?;
        let content_swaps = reader.u32()?;
        let content_manifest = reader.u64()?;
        let unit_hash = reader.u64()?;
        let reason = reader.str_u32("reason", 1024)?;
        Ok(Self {
            in_reply_to,
            status,
            applied_tick,
            content_swaps,
            content_manifest,
            unit_hash,
            reason,
        })
    }
}

/// Requests an offline preview run of a Sigil unit (contract §13, message id `0x0022`, `T→E`).
/// In protocol v1 the engine always answers `Error(NotSupported)` (the editor preview uses
/// `sigilc simulate` instead, project ADR-0010); the payload is still defined so the codec and
/// its fixtures are complete for when a later version implements it.
#[derive(Clone, PartialEq, Debug)]
pub struct SigilPreview {
    /// `AssetPath` of the unit to preview.
    pub unit_path: String,
    /// Binary `SigilUnit` bytes; at most `MAX_UNIT_BYTES`.
    pub unit_bytes: Vec<u8>,
    /// Number of ticks to simulate.
    pub ticks: u32,
    /// Optional aim-target position sampled during the preview.
    pub target: Option<[f32; 2]>,
}

impl SigilPreview {
    /// Encodes this payload (contract §2 rule 9): fails with `FieldTooLong` for the
    /// first field whose length or count exceeds its declared maximum.
    pub fn encode(&self, out: &mut Vec<u8>) -> Result<(), ProtocolError> {
        let mut writer = Writer::new(out);
        writer.str_u32("unit_path", 255, &self.unit_path)?;
        writer.bytes_u32("unit_bytes", 8388608, &self.unit_bytes)?;
        writer.u32(self.ticks);
        match &self.target {
            Some(value) => {
                writer.option_tag(true);
                writer.array_f32(value);
            }
            None => writer.option_tag(false),
        }
        Ok(())
    }

    /// Decodes this payload from exactly `bytes`: [`ProtocolError::TrailingBytes`] if
    /// any byte is left over (contract §13).
    pub fn decode(bytes: &[u8]) -> Result<Self, ProtocolError> {
        let mut reader = Reader::new(bytes);
        let value = Self::decode_from(&mut reader)?;
        reader.finish()?;
        Ok(value)
    }

    /// Decodes this payload from `reader`, leaving the read head after its last byte
    /// and any trailing bytes unconsumed (used when nested inside a `vec`/`option`;
    /// only the outermost [`Self::decode`] enforces "no trailing bytes").
    fn decode_from(reader: &mut Reader<'_>) -> Result<Self, ProtocolError> {
        let unit_path = reader.str_u32("unit_path", 255)?;
        let unit_bytes = reader.bytes_u32("unit_bytes", 8388608)?;
        let ticks = reader.u32()?;
        let target = if reader.option_tag("target")? {
            Some(reader.array_f32::<2>()?)
        } else {
            None
        };
        Ok(Self {
            unit_path,
            unit_bytes,
            ticks,
            target,
        })
    }
}

/// Message catalogue metadata (contract §13 "Nachrichtenkatalog"): id, direction and
/// payload type. Building the actual dispatch (`Message` enum, `to_frame`/`from_frame`,
/// the handshake) is Plan-0002 WP8.2, not this module; these constants exist so that
/// work can read the catalogue from the same generated source as the payload types
/// instead of re-copying it from the contract. Plain `u16` rather than
/// `grimoire_debug::MessageId` on purpose: this file has no dependency on any
/// particular crate's own wrapper type.
pub mod catalogue {

    /// `Hello` payload, direction T↔E.
    /// Handshake request/response.
    pub const HELLO: u16 = 0x0001;
    /// `ErrorMsg` payload, direction T↔E.
    /// Protocol- or application-level error.
    pub const ERROR: u16 = 0x0002;
    /// `LogMsg` payload, direction E→T.
    /// One forwarded engine log line.
    pub const LOG: u16 = 0x0003;
    /// `Stats` payload, direction E→T.
    /// Per-frame profiler snapshot.
    pub const STATS: u16 = 0x0010;
    /// `SwapSigilUnit` payload, direction T→E.
    /// Hot-swap request.
    pub const SWAP_SIGIL_UNIT: u16 = 0x0020;
    /// `SwapAck` payload, direction E→T.
    /// Hot-swap acknowledgement.
    pub const SWAP_ACK: u16 = 0x0021;
    /// `SigilPreview` payload, direction T→E.
    /// Offline preview request (`NotSupported` in v1).
    pub const SIGIL_PREVIEW: u16 = 0x0022;
}
